#!/usr/bin/env python3
"""Materialize a concrete per-case controller and frozen spec before execution."""
import argparse,ast,hashlib,json,pathlib,re
ap=argparse.ArgumentParser();ap.add_argument('--run-id',required=True);ap.add_argument('--case-key',required=True);args=ap.parse_args();assert re.fullmatch(r'L014-R\d{3}',args.run_id);R=pathlib.Path(__file__).resolve().parents[1];p=json.loads((R/'specs/L014-protocol.json').read_text());assert args.case_key in p['cases'];manifest=json.loads((R/p['input_manifest']).read_text());by={x['label']:x for x in manifest['fixtures']};extra=['specs/L014-protocol.json',p['candidate'],p['input_manifest'],*[by[x]['path'] for x in p['cases'][args.case_key]]];base=R/'scripts/run_L012_R002_tokenizer.py';s=base.read_text().replace('L012-R002',args.run_id).replace('l012-cpu','l014-cpu').replace('20261019-r002','20261019-'+args.run_id.split('-')[1].lower()).replace('bench_tokenizer_cap_image.py','bench_tokenizer_drain_image.py').replace('specs/L012-protocol.json','specs/L014-protocol.json');i=s.index('extra_paths=');j=s.index("payload['extra_inputs']",i);s=s[:i]+'extra_paths='+repr(extra)+'\n'+s[j:];s=s.replace("payload['case_key']='tokenizer-cpu-c3'","payload['case_key']="+repr(args.case_key));ast.parse(s);controller=R/'scripts'/('run_'+args.run_id.replace('-','_')+'_tokenizer.py');controller.open('x').write(s)
build={'run_id':args.run_id,'case_key':args.case_key,'base_controller_sha256':hashlib.sha256(base.read_bytes()).hexdigest(),'materializer_sha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest(),'controller_sha256':hashlib.sha256(controller.read_bytes()).hexdigest(),'extra_inputs':{f:hashlib.sha256((R/f).read_bytes()).hexdigest() for f in extra}};(R/'specs'/(args.run_id+'-build.json')).open('x').write(json.dumps(build,indent=2)+'\n');inputs=[str(controller.relative_to(R)),'scripts/bench_tokenizer_drain_image.py','scripts/probe_target_image_cpu.py','scripts/execute_frozen.py','specs/L010-cpu-source-hashes.json','specs/L010-cpu-model-hashes.json','specs/'+args.run_id+'-build.json',*extra,*['sources/installed/'+f for f in json.loads((R/'specs/L010-cpu-source-hashes.json').read_text())]];spec={'command':['python3',str(controller.relative_to(R))],'receipt_dir':'runs/'+args.run_id+'-frozen-controller','timeout_seconds':260,'inputs':{f:hashlib.sha256((R/f).read_bytes()).hexdigest() for f in inputs},'scope':'Clean actual CPU installed/candidate paired benchmark; no wrappers or method overrides, no serving result.'};(R/'specs'/(args.run_id+'.json')).open('x').write(json.dumps(spec,indent=2)+'\n');print(json.dumps(build))
